with rr as (select s.id as src, (e ->> 'to')::uuid as tgt, e ->> 'assign' as role from wf_spaces s, jsonb_array_elements(coalesce(s.rules, '[]'::jsonb)) e where coalesce(e ->> 'assign', '') != '' and coalesce(e ->> 'to', '') ~* '^[0-9a-f-]{36}$'), c as (select b.id, rr.role, (select t from wf_teams t where t.division_id = b.division_id and t.id::text in (select value from jsonb_each_text(coalesce(b.fields, '{}'::jsonb))) order by t.name limit 1) as team from wf_bids b join rr on b.space_id = rr.tgt join wf_bids o on o.id = b.origin_bid_id and o.space_id = rr.src), p as (select c.id, c.role, (c.team).name as team_name, (select x.id::text from wf_people x where x.id::text in (select jsonb_array_elements_text(coalesce((c.team).members, '[]'::jsonb))) and lower(coalesce(x.role, '')) = lower(c.role) order by x.name limit 1) as pid from c), q as (select p.*, (select x.name from wf_people x where x.id::text = p.pid) as pname, (extract(epoch from now()) * 1000)::bigint as ms from p), upd as (update wf_bids b set assignee = q.pid, reporter = coalesce(q.pid, ''), history = coalesce(b.history, '[]'::jsonb) || (case when coalesce(q.pid, '') is distinct from coalesce(b.assignee, '') then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q.ms, 'field', 'Assignee', 'from', coalesce(b.assignee, ''), 'to', coalesce(q.pid, ''))) else '[]'::jsonb end) || (case when coalesce(q.pid, '') is distinct from coalesce(b.reporter, '') then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q.ms, 'field', 'Reporter', 'from', coalesce((select x.name from wf_people x where x.id::text = b.reporter), nullif(b.reporter, ''), 'None'), 'to', coalesce(q.pname, 'None'), 'toId', coalesce(q.pid, ''))) else '[]'::jsonb end) || (case when q.pid is null then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q.ms, 'field', 'note', 'text', case when q.team_name is null then 'No team is set on this bid, so the assignee and reporter are unknown.' else 'Nobody on ' || q.team_name || ' has the role ' || q.role || ', so the assignee and reporter are unknown.' end)) else '[]'::jsonb end), updated_at = now() from q where b.id = q.id and (coalesce(q.pid, '') is distinct from coalesce(b.assignee, '') or coalesce(q.pid, '') is distinct from coalesce(b.reporter, '')) returning b.id, q.ms, q.pid), ins as (insert into wf_notify (bid_id, through) select id::text, ms from upd on conflict (bid_id) do update set through = greatest(wf_notify.through, excluded.through) returning 1) select count(*) as bids_updated, count(pid) as given_a_person, count(*) - count(pid) as left_unknown from upd;
